function createPerson(color) {
    // Base humanoid structure
    let person = new THREE.Group();
    person.name = "Person";

    // Torso (simple box)
    let torso = new THREE.Mesh(
        new THREE.BoxGeometry(0.5, 2, 0.5),
        new THREE.MeshPhongMaterial({ color: color })
    );
    torso.position.y = 1;
    person.add(torso);

    // Head (simple sphere)
    let head = new THREE.Mesh(
        new THREE.SphereGeometry(0.3, 16, 16),
        new THREE.MeshPhongMaterial({ color: color })
    );
    head.position.y = 2.5;
    person.add(head);

    // Legs (simple cylinders)
    const legHeight = 1.5;
    const legRadius = 0.15;

    let leftLeg = new THREE.Mesh(
        new THREE.CylinderGeometry(legRadius, legRadius, legHeight, 8),
        new THREE.MeshPhongMaterial({ color: color })
    );
    leftLeg.position.set(-0.15, legHeight / 2, 0);
    person.add(leftLeg);

    let rightLeg = new THREE.Mesh(
        new THREE.CylinderGeometry(legRadius, legRadius, legHeight, 8),
        new THREE.MeshPhongMaterial({ color: color })
    );
    rightLeg.position.set(0.15, legHeight / 2, 0);
    person.add(rightLeg);

    // Arms (simple boxes/cylinders, hanging down)
    const armLength = 1.2;
    const armRadius = 0.08;

    let leftArm = new THREE.Mesh(
        new THREE.CylinderGeometry(armRadius, armRadius, armLength, 8),
        new THREE.MeshPhongMaterial({ color: color })
    );
    leftArm.position.set(-0.4, 1.5, 0);
    person.add(leftArm);

    let rightArm = new THREE.Mesh(
        new THREE.CylinderGeometry(armRadius, armRadius, armLength, 8),
        new THREE.MeshPhongMaterial({ color: color })
    );
    rightArm.position.set(0.4, 1.5, 0);
    person.add(rightArm);

    // User data contract fulfillment
    person.userData = {
        leftLeg: leftLeg,
        rightLeg: rightLeg,
        isWalking: false,
        currentFloor: 1, // Initialize floor
        inElevator: false // Initialize state
    };

    return person;
}

// Global Contract Constants (must be top-level const)
const FLOOR_HEIGHT = 3;
const FLOOR_COUNT = 6;
const BUILDING_WIDTH = 20;
const BUILDING_DEPTH = 15;
const SHAFT_WIDTH = 5;
const SHAFT_DEPTH = 5;
const ELEVATOR_SPEED = 2;
const PERSON_MOVE_SPEED = 1;

// Global Contract Variables (must be top-level let)
let scene;
let camera;
let renderer;
let controls;
let elevatorCar;
let people = [];

// State variables
let animationSpeed = 1.0;
let emptyFloor = 2; // Arbitrary starting empty floor

// Simulation loop control
let isRunning = false;
let clock = new THREE.Clock();

function startSimulation() {
    console.log("Starting Elevator Simulation...");

    // 1. Setup Scene
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x111111);

    // 2. Camera
    camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(BUILDING_WIDTH / 2, FLOOR_COUNT * FLOOR_HEIGHT / 2, BUILDING_DEPTH / 2);

    // 3. Renderer
    renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // 4. Lights
    const ambientLight = new THREE.AmbientLight(0x404040, 2); // soft white light
    scene.add(ambientLight);

    const directionalLight1 = new THREE.DirectionalLight(0xffffff, 1);
    directionalLight1.position.set(5, 10, 5);
    scene.add(directionalLight1);

    const directionalLight2 = new THREE.DirectionalLight(0xffffff, 1);
    directionalLight2.position.set(-5, -10, -5);
    scene.add(directionalLight2);

    // 5. Controls
    controls = new THREE.OrbitControls(camera, renderer.domElement);
    controls.target.set(0, 3, 0); // Center controls on the middle of the building/shaft
    controls.update();

    // 6. Initialize World Elements
    createBuilding();
    createElevatorCar();
    initializePeople();

    // 7. Handle Resize
    window.addEventListener('resize', onWindowResize, false);

    // 8. Start Animation
    isRunning = true;
    animate();
}

function onWindowResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
}

function animate() {
    if (!isRunning) return;
    requestAnimationFrame(animate);

    const delta = clock.getDelta() * animationSpeed;

    controls.update();

    // Placeholder for simulation updates in later passes
    // updateSimulation(delta); 

    renderer.render(scene, camera);
}

// --- Pass 1 Placeholders ---

function createBuilding() {
    console.log("Building creation placeholder.");
}

function createElevatorCar() {
    console.log("Elevator car creation placeholder.");
    // Placeholder for the required Group object
    elevatorCar = new THREE.Group();
    scene.add(elevatorCar);
    return elevatorCar;
}

function initializePeople() {
    // Placeholder for creating 5 people
    console.log("People initialization placeholder.");
}


// Auto-start logic
if (document.readyState === "loading") {
    window.addEventListener("DOMContentLoaded", startSimulation);
} else {
    startSimulation();
}

