function floorY(floorNumber) {
    return (floorNumber - 1) * FLOOR_HEIGHT + FLOOR_HEIGHT / 2;
}

function createBuilding() {
    // 1. Ground Floor and Roof (Solid)
    const groundGeometry = new THREE.BoxGeometry(BUILDING_WIDTH, 1, BUILDING_DEPTH);
    const groundMaterial = new THREE.MeshPhongMaterial({ color: 0x808080 });
    const ground = new THREE.Mesh(groundGeometry, groundMaterial);
    ground.position.set(0, 0.5, 0);
    scene.add(ground);

    const roofGeometry = new THREE.BoxGeometry(BUILDING_WIDTH, 0.5, BUILDING_DEPTH);
    const roofMaterial = new THREE.MeshPhongMaterial({ color: 0x808080 });
    const roof = new THREE.Mesh(roofGeometry, roofMaterial);
    roof.position.set(0, (FLOOR_COUNT * FLOOR_HEIGHT) - 0.25, 0);
    scene.add(roof);

    // 2. Walls (Semi-transparent blue)
    const wallMaterial = new THREE.MeshPhongMaterial({ color: 0x9999ff, transparent: true, opacity: 0.2 });

    // Outer walls (Perimeter)
    const wallHeight = FLOOR_COUNT * FLOOR_HEIGHT;
    const wallGeometry = new THREE.BoxGeometry(BUILDING_WIDTH, wallHeight, 0.2);

    // Front wall (Y=0, Z=BUILDING_DEPTH/2)
    const frontWall = new THREE.Mesh(new THREE.BoxGeometry(BUILDING_WIDTH, wallHeight, 0.2), wallMaterial);
    frontWall.position.set(0, wallHeight / 2, BUILDING_DEPTH / 2);
    scene.add(frontWall);

    // Back wall (Y=0, Z=-BUILDING_DEPTH/2)
    const backWall = new THREE.Mesh(new THREE.BoxGeometry(BUILDING_WIDTH, wallHeight, 0.2), wallMaterial);
    backWall.position.set(0, wallHeight / 2, -BUILDING_DEPTH / 2);
    scene.add(backWall);

    // Left wall (X=-BUILDING_WIDTH/2, Z=0)
    const leftWall = new THREE.Mesh(new THREE.BoxGeometry(0.2, wallHeight, BUILDING_DEPTH), wallMaterial);
    leftWall.position.set(-BUILDING_WIDTH / 2, wallHeight / 2, 0);
    scene.add(leftWall);

    // Right wall (X=BUILDING_WIDTH/2, Z=0)
    const rightWall = new THREE.Mesh(new THREE.BoxGeometry(0.2, wallHeight, BUILDING_DEPTH), wallMaterial);
    rightWall.position.set(BUILDING_WIDTH / 2, wallHeight / 2, 0);
    scene.add(rightWall);

    // 3. Inner Floors (Gray, transparent)
    const floorMaterial = new THREE.MeshPhongMaterial({ color: 0xcccccc, transparent: true, opacity: 0.3 });

    for (let i = 1; i <= FLOOR_COUNT; i++) {
        const floorGeometry = new THREE.BoxGeometry(BUILDING_WIDTH, 0.2, BUILDING_DEPTH);
        const floor = new THREE.Mesh(floorGeometry, floorMaterial);
        // Position floor centered vertically at floorY
        floor.position.set(0, floorY(i), 0);
        scene.add(floor);
    }

    // 4. Central Elevator Shaft Opening (Visual guide)
    const shaftGeometry = new THREE.BoxGeometry(SHAFT_WIDTH, wallHeight, SHAFT_DEPTH);
    const shaftMaterial = new THREE.MeshPhongMaterial({ color: 0x333333, transparent: true, opacity: 0.5 });
    const shaft = new THREE.Mesh(shaftGeometry, shaftMaterial);
    shaft.position.set(0, wallHeight / 2, 0);
    scene.add(shaft);
}

function createElevatorCar() {
    // The car group
    const carGroup = new THREE.Group();

    // Car dimensions (relative to the shaft)
    const carWidth = SHAFT_WIDTH - 1;
    const carDepth = SHAFT_DEPTH - 1;

    // Car body (Yellow frame - semi-transparent)
    const carMaterial = new THREE.MeshPhongMaterial({ color: 0xffff00, transparent: true, opacity: 0.5 });
    const carGeometry = new THREE.BoxGeometry(carWidth, FLOOR_COUNT * FLOOR_HEIGHT, carDepth);
    const carBody = new THREE.Mesh(carGeometry, carMaterial);
    carBody.position.y = (FLOOR_COUNT * FLOOR_HEIGHT) / 2; // Center vertically initially
    carGroup.add(carBody);

    // Doors (Dark yellow)
    const doorMaterial = new THREE.MeshPhongMaterial({ color: 0xcccc00, transparent: true, opacity: 0.7 });
    const doorThickness = 0.2;
    const doorHeight = FLOOR_COUNT * FLOOR_HEIGHT;
    const halfCarWidth = carWidth / 2;

    // Left Door
    const leftDoorGeometry = new THREE.BoxGeometry(halfCarWidth - 0.1, doorHeight, doorThickness);
    const leftDoor = new THREE.Mesh(leftDoorGeometry, doorMaterial);
    leftDoor.position.set(-(halfCarWidth / 2), 0, 0);
    carGroup.add(leftDoor);

    // Right Door
    const rightDoorGeometry = new THREE.BoxGeometry(halfCarWidth - 0.1, doorHeight, doorThickness);
    const rightDoor = new THREE.Mesh(rightDoorGeometry, doorMaterial);
    rightDoor.position.set((halfCarWidth / 2), 0, 0);
    carGroup.add(rightDoor);

    // Store doors on the group as required
    carGroup.leftDoor = leftDoor;
    carGroup.rightDoor = rightDoor;

    return carGroup;
}

function initializePeople() {
    // Placeholder for creating people in Pass 3
}

