// --- Animation and Movement Helpers ---

/** Utility to delay execution */
function delay(ms, done) {
    setTimeout(done, ms);
}

/** Animates doors sliding open or closing */
function animateDoors(open, done) {
    // Door animation state tracking
    if (window.doorAnimationRunning) {
        return () => {
            console.log("Door animation already running.");
            done();
        };
    }
    window.doorAnimationRunning = true;

    const leftDoor = elevatorCar.leftDoor;
    const rightDoor = elevatorCar.rightDoor;
    const doorWidth = SHAFT_WIDTH - 1 - 0.2; // Total width minus thickness of both doors
    const doorCenter = 0;

    // Target position for doors when open (half the car width away from center)
    const targetOffset = (carWidth / 2) + 0.1; 

    const doorAnimation = (time) => {
        let startTime = performance.now();

        const animateDoor = (door, targetX) => {
            const startX = door.position.x;
            const distance = targetX - startX;
            const duration = 0.5; // 500ms animation time

            function moveDoor(t) {
                door.position.x = startX + (distance * t);
                if (t < 1) {
                    requestAnimationFrame(moveDoor);
                }
            }
            requestAnimationFrame(moveDoor);
        };

        // Simplified implementation: just set final state after delay for visual observation
        if (open) {
            leftDoor.position.x = -(carWidth / 2) - 0.1;
            rightDoor.position.x = (carWidth / 2) + 0.1;
        } else {
            leftDoor.position.x = -(carWidth / 2) + 0.1;
            rightDoor.position.x = (carWidth / 2) - 0.1;
        }

        // Use a short delay to simulate animation time for the visual check
        delay(300, () => {
            window.doorAnimationRunning = false;
            done();
        });
    };

    requestAnimationFrame(doorAnimation);
}

/** Animates elevator moving to a target floor */
function animateElevatorToFloor(targetFloor, done) {
    // Animation state tracking
    if (window.elevatorMoving) {
        return () => {
            console.log("Elevator already moving.");
            done();
        };
    }
    window.elevatorMoving = true;

    const startY = elevatorCar.position.y;
    const targetY = floorY(targetFloor);
    const distance = Math.abs(targetY - startY);

    const duration = distance / ELEVATOR_SPEED; // Time proportional to distance and speed setting

    const elevatorMove = (time) => {
        let startTime = performance.now();

        const animateCar = () => {
            const elapsed = performance.now() - startTime;
            const t = Math.min(1, elapsed / (duration * 1000)); // Normalized time [0, 1]

            // Smooth interpolation (simple linear here)
            elevatorCar.position.y = startY + (targetY - startY) * t;

            if (t < 1) {
                requestAnimationFrame(animateCar);
            }
        };

        requestAnimationFrame(animateCar);

        // Wait for movement to finish
        delay(Math.max(100, Math.round(duration * 1000)), () => {
            window.elevatorMoving = false;
            done();
        });
    };

    requestAnimationFrame(elevatorMove);
}

/** Walks person along Z axis */
function walkPersonToZ(person, targetZ, done) {
    if (person.userData.isWalking) {
        console.log("Person is already walking.");
        done();
    }
    person.userData.isWalking = true;

    const startZ = person.position.z;
    const distance = Math.abs(targetZ - startZ);
    const duration = distance / PERSON_MOVE_SPEED;

    const walkingMovement = (time) => {
        let startTime = performance.now();

        const walkPerson = () => {
            const elapsed = performance.now() - startTime;
            const t = Math.min(1, elapsed / (duration * 1000)); 

            // Move along Z axis
            person.position.z = startZ + (targetZ - startZ) * t;

            if (t < 1) {
                requestAnimationFrame(walkPerson);
            }
        };

        requestAnimationFrame(walkPerson);

        // Wait for movement to finish
        delay(Math.max(100, Math.round(duration * 1000)), () => {
            person.userData.isWalking = false;
            done();
        });
}

/** Controls leg movement via sine wave */
function animateWalkingLegs(time) {
    const speed = 5; // Frequency of walking

    // Update leg rotations for the person currently walking
    people.forEach(person => {
        if (person.userData.isWalking) {
            const t = time / 1000;

            // Left Leg: Sine wave, phase 0
            const angleL = Math.sin(t * speed) * Math.PI / 4; // Swing max 45 degrees
            person.userData.leftLeg.rotation.x = angleL;

            // Right Leg: Sine wave, phase PI (opposite)
            const angleR = Math.sin(t * speed + Math.PI) * Math.PI / 4;
            person.userData.rightLeg.rotation.x = angleR;
        } else {
            // Reset leg rotations when walking stops
            people.forEach(p => {
                if (p === person) {
                    person.userData.leftLeg.rotation.x = 0;
                    person.userData.rightLeg.rotation.x = 0;
                }
            });
        }
    });
}
// --- End Animation and Movement Helpers ---


// Auto-start logic
