        let startTime = performance.now();

        const animateCar = () => {
            const elapsed = performance.now() - startTime;
            const t = Math.min(1, elapsed / (duration * 1000)); // Normalized time [0, 1]

            // Smooth interpolation (simple linear here)
            elevatorCar.position.y = startY + (targetY - startY) * t;

            if (t < 1) {
                requestAnimationFrame(animateCar);
            }
        };

        requestAnimationFrame(animateCar);

        // Wait for movement to finish
        delay(Math.max(100, Math.round(duration * 1000)), () => {
            window.elevatorMoving = false;
            done();
        });
    };

    requestAnimationFrame(elevatorMove);
}

/** Walks person along Z axis */
function walkPersonToZ(person, targetZ, done) {
    if (person.userData.isWalking) {
        console.log("Person is already walking.");
        done();
    }
    person.userData.isWalking = true;

    const startZ = person.position.z;
    const distance = Math.abs(targetZ - startZ);
    const duration = distance / PERSON_MOVE_SPEED;

    const walkingMovement = (time) => {
        let startTime = performance.now();

        const walkPerson = () => {
            const elapsed = performance.now() - startTime;
            const t = Math.min(1, elapsed / (duration * 1000)); 

            // Move along Z axis
            person.position.z = startZ + (targetZ - startZ) * t;

            if (t < 1) {
                requestAnimationFrame(walkPerson);
            }
        };

        requestAnimationFrame(walkPerson);

        // Wait for movement to finish
        delay(Math.max(100, Math.round(duration * 1000)), () => {
            person.userData.isWalking = false;
            done();
        });
    };

    requestAnimationFrame(walkingMovement);
}

/** Controls leg movement via sine wave */
function animateWalkingLegs(time) {
    const speed = 5; // Frequency of walking

    // Update leg rotations for the person currently walking
    people.forEach(person => {
        if (person.userData.isWalking) {
            const t = time / 1000;

            // Left Leg: Sine wave, phase 0
            const angleL = Math.sin(t * speed) * Math.PI / 4; // Swing max 45 degrees
            person.userData.leftLeg.rotation.x = angleL;

            // Right Leg: Sine wave, phase PI (opposite)
            const angleR = Math.sin(t * speed + Math.PI) * Math.PI / 4;
            person.userData.rightLeg.rotation.x = angleR;
        } else {
            // Reset leg rotations when walking stops
            people.forEach(p => {
                if (p === person) {
                    person.userData.leftLeg.rotation.x = 0;
                    person.userData.rightLeg.rotation.x = 0;
                }
            });
        }
    });
}
