    controls.target.set(0, 3, 0); // Center controls on the middle of the building/shaft
    controls.update();

    // 6. Initialize World Elements
    createBuilding();
    createElevatorCar();
    initializePeople();

    // 7. Handle Resize
    window.addEventListener('resize', onWindowResize, false);

    // 8. Start Animation
    isRunning = true;
    animate();
}

